update.foreach:
update stock_location
set amount = amount - #{item.amount},
    locked_amount = locked_amount + #{item.amount}
where warehouse_id = #{item.warehouseId}
  and sku_id = #{item.skuId}
  and location_id = #{item.locationId}
  and amount >= #{item.amount}

update stock_location
set locked_amount = locked_amount - #{item.amount}
where warehouse_id = #{item.warehouseId}
  and sku_id = #{item.skuId}
  and location_id = #{item.locationId}
  and locked_amount >= #{item.amount}

mapper.select:
select id, warehouse_id, sku_id, location_id, amount, locked_amount
from stock_location
where warehouse_id = #{warehouseId}
  and sku_id = #{skuId}
  and location_id = #{locationId}
  and amount = 0
